#include <bits/stdc++.h>
using namespace std;

struct Item {
    string name;
    int q;
    long long v, m, l;
};

int n;
Item items[12];
long long bestVal;
int bestSol[12];
int curSol[12];
const long long capM = 20000000LL, capL = 25000000LL;
chrono::steady_clock::time_point startTime;

// Lagrangian bound: for given lambda, combine constraints: m + lambda*l <= capM + lambda*capL
// Then solve 1D bounded knapsack LP relaxation (greedy)
double lagrangianBound(int idx, long long rm, long long rl, long long curVal, double lambda) {
    double cap = (double)rm + lambda * (double)rl;
    double ub = (double)curVal;
    // Build efficiency order for remaining items
    // cost_i = m_i + lambda * l_i, value = v_i
    // Sort by v_i / cost_i descending
    static int ord[12];
    static double eff[12];
    int cnt = 0;
    for (int i = idx; i < n; i++) {
        ord[cnt] = i;
        double cost = (double)items[i].m + lambda * (double)items[i].l;
        eff[cnt] = (cost > 1e-12) ? (double)items[i].v / cost : 1e18;
        cnt++;
    }
    // Sort by efficiency desc
    for (int i = 0; i < cnt-1; i++)
        for (int j = i+1; j < cnt; j++)
            if (eff[j] > eff[i]) { swap(eff[i], eff[j]); swap(ord[i], ord[j]); }

    for (int i = 0; i < cnt; i++) {
        int ii = ord[i];
        double cost = (double)items[ii].m + lambda * (double)items[ii].l;
        long long maxByM = (items[ii].m > 0) ? rm / items[ii].m : (long long)items[ii].q;
        long long maxByL = (items[ii].l > 0) ? rl / items[ii].l : (long long)items[ii].q;
        long long canInt = min({(long long)items[ii].q, maxByM, maxByL});
        double canByCap = (cost > 1e-12) ? cap / cost : (double)items[ii].q;
        double canTake = min((double)canInt, canByCap);
        // Also can't exceed qty
        canTake = min(canTake, (double)items[ii].q);
        if (canTake >= items[ii].q) {
            ub += (double)items[ii].v * items[ii].q;
            cap -= cost * items[ii].q;
            // Don't update rm/rl here, they are for hard feasibility
        } else {
            ub += (double)items[ii].v * canTake;
            break;
        }
    }
    return ub;
}

double getBound(int idx, long long rm, long long rl, long long curVal) {
    // Try several lambda values and take the min (tightest bound)
    double best = 1e30;
    for (double lambda : {0.0, 0.1, 0.3, 0.5, 0.8, 1.0, 1.5, 2.0, 3.0, 5.0, 10.0, 20.0, 50.0, 100.0}) {
        double b = lagrangianBound(idx, rm, rl, curVal, lambda);
        if (b < best) best = b;
    }
    return best;
}

long long nodeCount = 0;

void solve(int idx, long long rm, long long rl, long long curVal) {
    if (idx == n) {
        if (curVal > bestVal) {
            bestVal = curVal;
            memcpy(bestSol, curSol, sizeof(bestSol));
        }
        return;
    }

    nodeCount++;
    if ((nodeCount & 0xFFF) == 0) {
        auto now = chrono::steady_clock::now();
        if (chrono::duration_cast<chrono::milliseconds>(now - startTime).count() > 900) return;
    }

    double ub = getBound(idx, rm, rl, curVal);
    if (ub <= (double)bestVal + 0.5) return;

    long long maxByM = (items[idx].m > 0) ? rm / items[idx].m : (long long)items[idx].q;
    long long maxByL = (items[idx].l > 0) ? rl / items[idx].l : (long long)items[idx].q;
    int maxTake = (int)min({(long long)items[idx].q, maxByM, maxByL});

    for (int k = maxTake; k >= 0; k--) {
        curSol[idx] = k;
        solve(idx + 1, rm - (long long)k * items[idx].m, rl - (long long)k * items[idx].l, curVal + (long long)k * items[idx].v);
        auto now = chrono::steady_clock::now();
        if (chrono::duration_cast<chrono::milliseconds>(now - startTime).count() > 900) return;
    }
    curSol[idx] = 0;
}

int main(){
    startTime = chrono::steady_clock::now();
    string input((istreambuf_iterator<char>(cin)), istreambuf_iterator<char>());

    vector<pair<string, vector<long long>>> entries;
    size_t pos = 0;
    while(true) {
        pos = input.find('"', pos);
        if (pos == string::npos) break;
        size_t end = input.find('"', pos+1);
        string key = input.substr(pos+1, end-pos-1);
        pos = end+1;
        size_t br = input.find('[', pos);
        if (br == string::npos) break;
        size_t br2 = input.find(']', br);
        string arr = input.substr(br+1, br2-br-1);
        pos = br2+1;
        vector<long long> nums;
        stringstream ss(arr);
        string token;
        while(getline(ss, token, ',')) {
            long long val = 0;
            for (char c : token) if (c >= '0' && c <= '9') val = val*10 + (c-'0');
            nums.push_back(val);
        }
        if (nums.size() == 4) entries.push_back({key, nums});
    }

    n = entries.size();
    map<string,int> nameToIdx;
    for (int i = 0; i < n; i++) {
        items[i].name = entries[i].first;
        items[i].q = (int)entries[i].second[0];
        items[i].v = entries[i].second[1];
        items[i].m = entries[i].second[2];
        items[i].l = entries[i].second[3];
        nameToIdx[entries[i].first] = i;
    }

    sort(items, items+n, [](const Item& a, const Item& b){
        double da = (double)a.v / max(a.m * 25.0, a.l * 20.0);
        double db = (double)b.v / max(b.m * 25.0, b.l * 20.0);
        return da > db;
    });

    bestVal = -1;
    memset(bestSol, 0, sizeof(bestSol));
    memset(curSol, 0, sizeof(curSol));

    solve(0, capM, capL, 0);

    cout << "{\n";
    for (int i = 0; i < n; i++) {
        cout << " \"" << items[i].name << "\": " << bestSol[i];
        if (i < n-1) cout << ",";
        cout << "\n";
    }
    cout << "}\n";

    return 0;
}
